export const lessons = [
 {id:1,group:'摄影基础',title:'焦距改变取景，站位改变透视',short:'先学会选择：拍整个世界，还是一个细节。',time:30,image:'bridge',tags:['Focal Length','视角','透视'],lab:'crop',goal:'看懂 0.5×、1×、2×、4×、8×；分清放大画面和走近拍摄。',concepts:[['焦距先理解成取景范围','站位不变时，等效焦距越短，拍进去的范围越广；越长，范围越窄，同一主体在画面中越大。等效焦距把不同尺寸传感器的视角换算到同一标准，并不是手机镜头的实际长度。'],['三个摄像头，多个取景档位','17 Pro 的超广角为等效13mm（0.5×），主摄24mm（1×），长焦100mm（4×）。2×为主摄中央区域裁切，8×为长焦中央区域裁切，Apple 称其为12MP“光学品质”。它们不是额外两颗镜头，也不是连续纯光学变焦。'],['透视来自你站在哪里','靠近前景，前景相对背景会变大；退远再用较长焦段保持主体大小，背景会相对显得更大。保持站位只裁切，不会改变前后物体的比例。背景虚化和透视是不同概念。']],steps:['打开相机 → 照片 → 后置摄像头，先用1×。','站稳并保持手机位置，依次点击0.5×、1×、2×、4×。找不到档位时按住变焦数字，拖动滑杆。','比较的不只是主体大小，还要看画面边缘增加了什么、删掉了什么。'],scene:'在金门大桥观景点，先用1×交代桥与海湾的关系，再用4×寻找桥塔局部。想拍朋友与更大的背景桥：退远，再用较长焦段维持朋友的大小。',tasks:['同一站位拍0.5×、1×、2×、4×各一张，选出最明确的一张。','近处1×、远处2×各拍一张杯子，让杯子一样大，观察背景比例。'],question:'朋友在画面中大小不变，怎样让身后的大桥相对更大？',options:['走近朋友，用广角拍','退远一些，再用较长焦段','站位不变，直接裁切'],answer:1,explain:'退远改变了朋友与大桥的相对透视关系；较长焦段帮助维持朋友在画面中的大小。',tip:'今天不追求最远的变焦。先决定观众第一眼应该看哪里。',refs:['specs','focus']},
 {id:2,group:'摄影基础',title:'让该清楚的清楚，让光线听你的',short:'轻点、拖动、长按：掌握最常用的三个动作。',time:30,image:'forest',tags:['Focus','Exposure','AE/AF Lock'],lab:'exposure',goal:'会选择对焦区域、调整亮度，并知道什么时候需要锁定。',concepts:[['对焦选择的是距离','对焦让某个距离附近的细节清楚。点刷子不代表只有刷子轮廓清楚，同一距离的台面也可能清楚。对焦不能修复手抖和运动拖影。'],['曝光控制整体明暗','相机不知道你想保留窗外的云，还是窗内的人。点不同区域时，自动测光可能一起改变；曝光补偿是在自动曝光建议的基础上，让画面更亮或更暗。它不是只改变点击区域。'],['锁定与追踪不一样','AE 是自动曝光，AF 是自动对焦。AE/AF Lock 暂时保持当前设置；主体走近、你前后移动后，原来的对焦距离可能不再合适，需要重新对焦。锁定不是追踪。']],steps:['相机 → 照片 → 1×，轻点你希望清楚的主体。','上下拖动对焦框旁的小太阳：上亮、下暗；看亮部是否仍有纹理。','按住主体直到出现“自动曝光/自动对焦锁定”。锁定后仍可拖小太阳调整；轻点画面解锁。','数值曝光补偿：从底部模式区域向上轻扫 → 曝光（±）→ 拖动。0是自动建议，负值更暗、正值更亮；它不同时锁住对焦。'],scene:'拍晚霞时，先把天空从发白调到有层次，再检查前景是不是太暗。逆光人像可能需要换站位或找反光，不能指望一根滑杆解决所有反差。',tasks:['前景放一本书，背景放包装盒；固定站位，分别点前景和背景拍两张。','窗边静物长按锁定，拍默认、偏暗、偏亮三张，比较主体和窗外细节。'],question:'锁定对焦后，朋友向你走近了，你应该怎样做？',options:['保持锁定，相机会自动追上','重新对焦到朋友','只把曝光调亮'],answer:1,explain:'锁定保持的是对焦设置，不会让清晰距离跟随朋友。重新对焦才能匹配新的距离。',tip:'先判断：是没对准焦，还是抖了？两种模糊需要不同处理。',refs:['focus']},
 {id:3,group:'摄影基础',title:'快门、ISO与光圈，分别在做什么',short:'看懂曝光三角，也看清手机能控制的边界。',time:45,image:'city',tags:['Shutter','ISO','Aperture'],lab:'motion',goal:'知道模糊和噪点从哪里来，不把相机教程中的参数直接套给手机。',concepts:[['快门是记录运动的时间','1/1000秒比1/30秒短得多。短时间更容易冻结篮球；长时间会把移动过程叠成轨迹，也更容易手抖。其他条件相同，时间更长会收集更多光。'],['ISO不是多进光的开关','ISO影响相机把捕获的信号映射成多亮的图像。在曝光不足时提高ISO能让照片更亮，但不能补回没有捕获的光子；通常会面临更多可见噪点或更小的高光余量。'],['光圈与传感器有各自的作用','f值越小，同焦距下的相对开口越大；它影响进光与景深。17 Pro各后摄为固定光圈：主摄f/1.78、超广角f/2.2、长焦f/2.8。人像模式的f值是计算虚化控制，不是物理叶片。传感器更大在条件合适时可改善集光能力，但不能只比一个尺寸就判断最终画质。']],steps:['原生相机不能像专业手动App那样直接指定每张照片的ISO和快门速度；今天用自动拍摄观察结果。','在明亮处和较暗处分别拍静止物体，再拍缓慢摆动的手。','照片App打开照片，向上轻扫或点信息，查看文件保留的快门、ISO、镜头等信息；不同文件可能缺少元数据。'],scene:'球馆里，防抖可以减少手机抖动，却不能冻结奔跑的球员。遇到拖影应争取更多光、减少过度变焦，或在以后需要时使用能指定快门的第三方摄影App。',tasks:['明亮与较暗环境各拍一次摆动的手，对比拖影。','记录两张照片的快门与ISO，说明哪一个更容易凝固动作。'],question:'防抖很强，但运动员仍有拖影，最可能缺什么？',options:['更短的记录时间','更多像素','更浓的滤镜'],answer:0,explain:'防抖处理相机移动；主体在曝光期间的移动需要较短快门时间来减轻。',tip:'曝光三角是理解工具；手机还会多帧合成，最终效果不只由一组参数决定。',refs:['specs']},
 {id:4,group:'摄影基础',title:'用光线和构图，让画面有主角',short:'从“这里很美”，到“我想让你看见这里”。',time:40,image:'bridge',tags:['Light','Composition','Color'],lab:'composition',goal:'识别光线方向，安排主体、背景和画面边缘。',concepts:[['先看光从哪里来','顺光容易看清颜色；侧光用明暗表现质感；逆光适合轮廓与剪影，但会增加主体和背景的亮度差。阴天的柔光适合人像与森林细节，不是只有晴天才能拍。'],['构图是在分配注意力','三分法只是起点。先问主角是谁，再用引导线、明暗和留白支持主角。拍完检查四个边缘：有没有半截路人、歪地平线或从头上长出来的杆子。'],['色彩先求关系','暖色日落和冷色海面能形成对比；红桥与低饱和雾气能突出主体。白平衡影响冷暖，但不要把所有照片都推成橙蓝。透视与建筑倾斜也要靠站位和手机角度控制。']],steps:['设置 → 相机 → 打开“网格”和“水平仪”（按系统显示名称选择）。','先用1×，让手机尽量水平，找一条线引导视线走向主体。','绕主体改变站位，比较顺光、侧光与逆光；拍摄前扫一眼四个边缘。'],scene:'金门大桥不一定要居中。可以让桥从画面角落延伸进去，也可以用海湾留白表达尺度。构图服务于想表达的感觉。',tasks:['同一个建筑拍居中、三分、引导线三种构图。','绕同一物体寻找三种方向的光，选最能显示质感的一张。'],question:'使用三分法后，背景的杆子仍穿过人物头部，首先怎么办？',options:['继续加饱和度','调整站位和背景关系','认为三分法一定更好'],answer:1,explain:'构图规则不会自动清理背景。稍微左右移动，常常比后期修复更直接。',tip:'先找到主体，再选择规则。留白也需要有意图。',refs:['focus']},
 {id:5,group:'旅行场景',title:'海岸与大桥：把辽阔拍出层次',short:'Lands End、Ocean Beach与太平洋海岸。',time:35,image:'coast',tags:['Landscape','Foreground','Coast'],lab:'composition',goal:'用前、中、远景构成空间，而不是把所有东西缩成一片。',concepts:[['广角需要有用的前景','0.5×会装进很多东西，也会让远处主体很小。近处岩石、沙纹或步道能把目光带进去；如果没有前景，1×或长焦取局部可能更有力。'],['水平线决定安定感','海平面稍微歪斜就容易被察觉。天空有戏时多留天空，海浪纹理有戏时多留海面；没有必要机械地各分一半。'],['海浪既是画面也是风险','浪花回撤时可形成线条。记录不同浪形比盲目连拍更有用。不要背对海面靠近湿岩，也不为构图跨越护栏或下到不熟悉的礁石。']],steps:['从安全平稳的位置用1×拍全景，打开水平仪检查地平线。','找到前景再尝试0.5×；保持地平线位置，比较主体有没有变得太小。','拍4×局部，观察海岸线与岩石形状；有风时双手握稳并收紧手肘。'],scene:'Lands End可以练引导线与层次；Ocean Beach可以练极简地平线与浪花。出发前查看官方步道、天气和海况信息，不在课程里预设现场一定可达。',tasks:['同一地点拍一张有前景、一张无前景，对比空间感。','拍全景、中景、细节三张，组成一组海岸故事。'],question:'0.5×拍海岸时远方大桥太小，怎么改善？',options:['所有风景必须坚持超广角','尝试1×或长焦，让主体更明确','把天空全部裁掉就一定好'],answer:1,explain:'风景不等于超广角。视角选择应该帮助主体被看见。',tip:'靠近前景之前，先确认脚下和海浪。',refs:['nps']},
 {id:6,group:'旅行场景',title:'红杉森林：拍到幽深，也拍到光',short:'为 Muir Woods、Steep Ravine 做准备。',time:35,image:'forest',tags:['Forest','Contrast','Texture'],lab:'exposure',goal:'处理森林中的暗部、亮斑、树干线条和绿色。',concepts:[['森林的困难是反差','树荫很暗，树冠间的天空很亮。相机可能难以同时保留两端细节。先决定主角是树皮、林间小路还是光束，避免让大片发白天空抢走注意力。'],['用重复与人物表达尺度','竖直树干构成节奏；弯曲小路带出深度。远处一个小人物可帮助理解树有多高，但拍摄应征得同行者配合，不阻挡步道。'],['绿色不需要越鲜艳越好','森林常混有绿色反光与冷色阴影。保留自然的棕色树皮和中性色，后期再小幅调整；过强饱和度会让叶片失去层次。']],steps:['用1×从林荫中的静止主体开始，轻点树皮或人物对焦。','画面有亮洞时，试着改变角度把天空排除；必要时向下调小太阳，保留亮处。','光线不足时倚靠稳定支撑，夜间模式出现后保持静止；人物需要配合不动。'],scene:'在 Muir Woods 先拍路径和树干，再拍树皮、蕨类等细节。Mt. Tamalpais与Steep Ravine的步道、天气和开放情况要另查官方信息；天暗前留出返回时间。',tasks:['树林里拍一张包含亮天空、一张排除亮天空，比较注意力。','用同一组照片表现“高大”“幽深”“细节”三个词。'],question:'树林照片被天空中的纯白亮洞吸引，优先尝试？',options:['换角度减少亮洞','加大所有颜色饱和度','一定开闪光灯照亮整片森林'],answer:0,explain:'构图先控制干扰源。手机闪光灯也无法照亮远处的整片森林。',tip:'光斑可以做主角，也可能是干扰。先决定你要哪个。',refs:['night','nps']},
 {id:7,group:'旅行场景',title:'日落不是一瞬间，而是一段光线',short:'Golden Hour、Blue Hour与海上晚霞。',time:35,image:'coast',tags:['Golden Hour','Blue Hour','Silhouette'],lab:'exposure',goal:'观察日落前后的光线变化，控制天空与前景的关系。',concepts:[['Golden Hour并非固定一小时','太阳接近地平线时，光线往往更暖、影子更长；Blue Hour是日出前或日落后的偏冷暮光阶段。持续时间随纬度、季节与天气变化，不能直接按固定时刻套用。'],['保留晚霞需要观察高光','天空颜色发白时可以降低曝光，但降低到前景全黑并不一定更好。想要人物细节，可以换方向找柔和补光；想要剪影，就让轮廓清晰地与背景分开。'],['太阳落下后别立刻收手机','云层可能继续变色，城市灯光开始与蓝色天空平衡。不过拍摄时间要服从安全返回与交通安排，不独自摸黑走陌生海岸。']],steps:['在预计日落前到安全位置，先用1×确定构图。','轻点主体确认对焦，长按锁定；拖动小太阳比较天空和前景。','每隔几分钟拍一张相同构图，从暖光记录到暮色。夜间模式出现时稳住手机。'],scene:'Ocean Beach面向海面可练日落与剪影；海湾方向可以练暮色与灯光。具体太阳方向、日落时间和云况在旅行前另行核实。',tasks:['同一构图拍日落前、日落附近、日落后三张。','同一人物拍一张保留脸部的照片和一张轮廓明确的剪影。'],question:'晚霞天空发白时，应该怎样调整？',options:['固定每张都调到最低亮度','逐步降低曝光，同时检查前景','只提高屏幕亮度'],answer:1,explain:'曝光取决于场景。以天空层次和前景表达的平衡为准，而非固定数值。',tip:'屏幕亮度影响观看感受，不等于改变照片曝光。',refs:['focus','night']},
 {id:8,group:'旅行场景',title:'城市夜景：稳住手机，留住灯光',short:'海湾灯火、街道与橱窗的明暗关系。',time:35,image:'city',tags:['Night Mode','Stability','Highlights'],lab:'exposure',goal:'区分相机抖动、主体拖影和灯光过曝。',concepts:[['夜间模式是多帧拍摄','原生夜间模式会在暗光下自动出现，并提供当前条件允许的时长选项。界面时长不等于可以任意输入的单帧快门。拍摄期间保持稳定，最终照片仍可能受移动主体影响。'],['支撑能稳住建筑，不能稳住路人','靠墙、栏杆等稳固支撑有助于静物。行人或车辆在拍摄中移动仍可能模糊。想冻结人就需要更短记录时间与更多光，不能只延长夜间模式。'],['灯光不该全部变成白团','小太阳下调一点，看看灯牌文字和灯光颜色能否保留。也可以接受深色阴影，夜景不一定要被拍成白天。脏镜头会让灯光出现雾状光晕。']],steps:['先擦镜头，用1×对准静止建筑，比较自动效果。','月亮图标出现时，点开夜间模式，在可用时长中选择；按下快门后直到结束都保持稳定。','手持和有支撑各拍一张；放大检查建筑边缘和路人，判断是哪一种模糊。'],scene:'海湾夜景先拍静止天际线，再用街边橱窗找亮处的人物。站在照明良好、人流合适的位置，留意周边与返回交通。',tasks:['同一夜景手持与支撑各拍一张。','拍灯牌默认曝光与较暗曝光，检查文字和颜色。'],question:'建筑清楚但路人有拖影，主要原因是什么？',options:['对焦一定错了','路人在拍摄期间移动','照片像素一定太低'],answer:1,explain:'相机稳定不代表主体静止。两种运动需要分开判断。',tip:'夜景先保清楚和高光，再考虑把阴影提亮多少。',refs:['night','focus']},
 {id:9,group:'旅行场景',title:'月亮与星空，不能用同一套方法',short:'建立可实现的目标，再谈银河与星轨。',time:40,image:'city',tags:['Moon','Stars','Limits'],lab:'motion',goal:'知道月亮是亮主体、星空是暗场景，并理解手机的上限。',concepts:[['月亮自身很亮','夜空很暗不代表月亮也暗。自动把整体提亮，月亮就可能变成白球。较长焦段让月亮大些，再降低曝光试着保留纹理；不要承诺手机能得到天文望远镜级细节。'],['星空需要暗天空和稳定','城市光污染、云层、月光都会影响星点。广角更容易容纳天空；手机稳定支撑后，夜间模式在可用范围内可尝试更长拍摄。星点与地景都要放大检查。'],['银河和星轨需要额外规划','银河可见方向与季节相关，星轨通常涉及长时间多张拍摄与合成。夜间模式时长不是无限长曝。不要把网络上的相机星空照片当成17 Pro保证能拍出的效果。']],steps:['拍月亮：照片模式尝试4×，对准月面，逐步降低曝光比较，不强行拉到最高数字变焦。','拍星空：安全暗处用1×，找远处亮物尝试对焦并锁定，再让手机有稳定支撑。','在夜间模式提供的范围内拍摄并检查；不把“最长”当成每次都更好的答案。'],scene:'本次无车旅行，优先在安全、可返回的位置做月亮和少量星点尝试。月相、银河方位与天气需要出发前另查；不为星空临时进入陌生山路。',tasks:['同一月亮拍默认和较低曝光，对比月面是否还有层次。','如果有安全条件，试一张有支撑的星空；没有条件可只完成月亮练习。'],question:'拍月亮变成纯白圆球，首先尝试什么？',options:['延长夜间模式到最大','降低曝光观察月面','开启手机闪光灯'],answer:1,explain:'月亮是明亮的被摄体。优先避免月面过曝；闪光灯无法照亮月亮。',tip:'拍到可辨认的月面或几颗清楚星点，也是有价值的第一步。',refs:['night','focus']},
 {id:10,group:'旅行场景',title:'NBA：抓住时机，也留下球馆的声音',short:'从校园球场练到 Chase Center。',time:40,image:'basket',tags:['Sports','Burst','Timing'],lab:'motion',goal:'理解运动抓拍、连拍时机、座位距离和变焦画质的取舍。',concepts:[['清楚动作需要短时间','篮球运动常需要约1/500秒到1/1000秒甚至更短，但这是理论起点，取决于动作与光线；原生照片模式不提供直接指定快门。球员模糊时，防抖不能替代短快门。'],['拍预判，而不只追随','观察罚球、接球和投篮的节奏，提前取景。连拍有助于挑选姿态，但不会自动消除每一帧的拖影。不要长时间锁焦后等球员跑向你。'],['球员特写之外还有故事','远座位用很高数字变焦不一定有足够细节。可以拍球场全景、出场、观众反应、记分牌和同行者。外场篮球示例不代表Chase Center实景或你的座位视角。']],steps:['先在校园球场找位置，用1×或4×比较主体大小与清晰度。','原生连拍：在照片模式把快门按钮向左滑并按住；在照片App挑选动作完整的帧。','球馆中优先等动作相对稳定的时刻；录像先试4K/60fps并查看暗处噪点，光线不足可比较30fps。','入场前核实比赛当日的相机、镜头、包、支架和录像规定；课程不承诺任何器材一定允许携带。'],scene:'Chase Center先拍一张交代座位与全场的画面，再尝试球员，最后记录观众气氛。克制录制长度，给自己留出看比赛的时间。',tasks:['校园球场拍一次短连拍，选出最佳姿态并说明时机。','以全景、动作、观众反应三种画面讲一个球场故事。'],question:'高倍变焦后球员细节很差，仍想记录比赛，应该？',options:['继续放大直到脸占满画面','减少过度变焦，拍动作和球馆氛围','认为手机什么都不能拍'],answer:1,explain:'选择设备能表达好的题材，比强求远处脸部特写更有收获。',tip:'先在校内练动作预判，再把注意力放回比赛本身。',refs:['burst','specs','chase']},
 {id:11,group:'旅行场景',title:'人像、街道与一顿饭，组成旅行',short:'让照片记录“你在这里”的感觉。',time:35,image:'city',tags:['Portrait','Street','Story'],lab:'composition',goal:'用人物、环境和细节构成一组旅行纪实。',concepts:[['人像先找光和背景','阴影边缘、窗边常有柔和光线。拍脸别用超广角贴太近；保持合适距离，再选较长焦段维持构图。人像模式的发丝与玻璃边缘可能处理不准，拍完检查。'],['街拍观察层次与时机','先找背景和光线，再等人物走入。手机保持适当水平能减少建筑倾斜。尊重不愿被拍的人，不挡路，也不为了画面走到车道。'],['美食与细节承担叙事','一张街景交代地点，一张人物建立情绪，一张食物或票根提供细节。顶拍适合平面餐盘，斜侧角适合有高度的食物；少用近距离闪光灯直射。']],steps:['人物先用照片模式拍一张，再比较人像模式，放大检查头发边缘。','餐桌靠近窗边，用1×或2×，调整距离避免挡住光源；太近无法对焦就退后。','每到一个地点拍全景、人物或动作、细节，避免只拍相同角度的地标。'],scene:'Chinatown练色彩与街道层次，Ferry Building练建筑和食物，同行者成为照片中的线索。具体路线与开放时间另行安排。',tasks:['一次出门只挑5张，顺序讲清地点、人物、活动与细节。','同一餐盘用顶拍与45度各一张，解释哪种更适合它。'],question:'人像模式把发丝边缘抠错了，应该？',options:['忽略，因为模式一定正确','检查原片，并比较普通照片模式','继续增加虚化到最大'],answer:1,explain:'计算虚化可能出错；普通模式有时更自然。',tip:'让同行者舒服，往往比多一个摄影技巧更重要。',refs:['focus']},
 {id:12,group:'整理与表达',title:'旅行视频：稳、短、有衔接',short:'把几段好镜头，连接成一段记忆。',time:45,image:'coast',tags:['4K','Frame Rate','Stabilization'],lab:'motion',goal:'理解帧率与防抖的取舍，完成30秒小片。',concepts:[['分辨率与帧率是两件事','4K描述空间细节，30或60fps描述每秒记录多少帧。60fps适合运动或适度慢放，通常需要更多光和存储；昏暗环境不要一味追求最高帧率。'],['稳不等于不动','站稳、双手握持、手肘靠近身体，先录不移动的镜头。移动时慢走，转身用身体带动。运动模式会裁切，并且更依赖光线；不是所有夜景都适用。'],['先想剪辑再拍','一段全景交代地点，一段中景交代动作，一段细节传达感觉。每个镜头保留头尾余量；录5–8秒比每次猛甩镜头更容易剪。收音时避风，不要用手挡住麦克风。']],steps:['设置 → 相机 → 录制视频，先以4K/30fps为日常起点；运动场景再比较60fps。','相机 → 视频。录制前确认横竖方向；有需要时长按主体锁定，主体改变距离后重新对焦。','先拍三个静止镜头，再试一次缓慢平移；检查边缘抖动和风噪。','HDR视频在兼容设备上效果好，但分享与剪辑链路可能显示不同；重要短片先做一次导出播放测试。'],scene:'海岸片用浪声开场、远景定位、鞋踩沙滩的细节收尾。球馆片可记录出场和欢呼，但遵守现场录像规定。',tasks:['用全景、中景、细节各一段，剪成30秒以内短片。','同一动作拍30与60fps，比较流畅度、暗处噪点和文件大小。'],question:'夜间60fps比30fps噪点明显，合理选择是？',options:['继续增加到最高帧率','比较30fps，结合动作需求取舍','只提高屏幕亮度'],answer:1,explain:'更高帧率限制每帧可用时间。暗光下，较低帧率往往更有余量。',tip:'今天先把三个静止镜头拍好，复杂运镜可以以后再学。',refs:['video','specs']},
 {id:13,group:'整理与表达',title:'HEIF、JPEG、ProRAW，怎样选',short:'格式服务于拍摄和分享，不是越大越专业。',time:30,image:'bridge',tags:['HEIF','ProRAW','HDR'],lab:'exposure',goal:'分清文件格式、像素、动态范围与HDR。',concepts:[['格式和像素不是同一件事','HEIF和JPEG是常见处理后图像格式；HEIF通常能以较小文件保存较好画质，JPEG兼容性广。12MP、24MP、48MP说的是像素数量，不代表是否RAW，也不保证暗光时越多越好。'],['ProRAW不是无处理的魔法底片','Apple ProRAW以DNG保存，结合RAW信息与计算摄影处理，为白平衡和明暗调整留出更多空间；文件更大，也需要认真编辑。不能救回完全没记录到的细节或运动模糊。'],['HDR涉及亮暗范围和显示','场景动态范围是最亮和最暗之间的跨度。多帧HDR有助于保留两端；HDR显示还能呈现更亮的高光。两者相关但不同，上传或导出后的呈现还取决于软件与屏幕。']],steps:['设置 → 相机 → 格式：查看“高效”和“兼容性最佳”，根据分享需求选择。','在格式中启用“Apple ProRAW与分辨率控制”（名称依系统可能略有不同），拍摄时检查RAW标识是否开启。','先用普通格式拍日常；选一处高反差场景再拍ProRAW，之后在照片信息中比较格式和文件大小。'],scene:'旅行大部分照片用日常格式即可；重要风景、且你打算后期时再考虑ProRAW。把存储留给真正值得保留的画面和视频。',tasks:['同场景拍普通照片和ProRAW，比较文件大小。','编辑两张照片的高光和白平衡，判断多出的空间是否对你有用。'],question:'ProRAW是否能修复手抖导致的模糊？',options:['能，RAW包含无限信息','不能，它不等于重新拍摄','只要提高分辨率就能'],answer:1,explain:'RAW提供编辑余量，不会重新记录曝光期间丢失的空间细节。',tip:'先拍好，再选择更大的格式；别让文件大小成为负担。',refs:['raw','specs']},
 {id:14,group:'整理与表达',title:'后期：还原感受，而不是堆叠滤镜',short:'先用免费自带的照片App完成一次编辑。',time:45,image:'forest',tags:['Editing','White Balance','Selection'],lab:'whitebalance',goal:'掌握筛选、裁切、明暗、色彩的基本顺序。',concepts:[['先选照片，再调参数','先删明显重复、失焦和拖影的照片，再选最有表达的一张。后期时间应该花在值得保留的照片上。裁切能加强构图，但不能替代改变站位带来的透视。'],['从大关系到小调整','先调水平与裁切，再调曝光、高光和阴影，最后看白平衡与饱和度。降低高光不保证恢复已完全过曝的信息；过度提阴影会暴露噪点。'],['颜色需要参照物','用白墙、灰衣服等中性色帮助判断偏色，但现场暖光本来就可以偏暖。清晰度和锐化过量会产生硬边，去噪过量又会抹平纹理。多次查看原图，防止越调越重。']],steps:['照片App → 打开照片 → 编辑，先裁切并校正水平。','依次小幅调整曝光、高光、阴影；再看暖色调、色调和鲜艳度等可用项目。','按住照片预览或使用界面的原图对比方式检查前后；不满意可还原。','先用自带App掌握顺序。以后需要局部遮罩或批量处理时再核实Lightroom当前免费与付费功能。'],scene:'同一天的海岸照片尽量保持一致的海水与天空颜色。森林照片保留树皮和阴影的自然层次，不把每片叶子都调成荧光绿。',tasks:['编辑一张海岸、一张森林或树木、一张人像，分别写下最关键的两步。','第二天重新看照片，检查是否调得过亮、过暖或过饱和。'],question:'后期通常先处理什么？',options:['先把锐化和饱和度拉满','筛选、水平和构图，再看明暗色彩','所有照片统一套最强滤镜'],answer:1,explain:'先解决照片的大结构，避免在构图不成立的照片上反复堆叠效果。',tip:'实验室里的色温是视觉近似示意，不是RAW白平衡的精确物理重算。',refs:['photos','raw']},
 {id:15,group:'整理与表达',title:'一套能坚持的旅行摄影工作流',short:'出发前、拍摄中、回到住处，各做几件事。',time:30,image:'coast',tags:['Workflow','Backup','Review'],lab:'composition',goal:'让拍摄、筛选、备份和复盘真正融入旅行。',concepts:[['出发前做减法','擦镜头、检查电量与可用存储，确认拍照格式和视频帧率。只带必要设备，不为了摄影增加难以负担的器材与行李。下载交通信息，留意天气和返程时间。'],['现场拍完要检查','每个重要场景先拍一张，再放大检查主体、边缘与高光。先拍安全且容易得到的画面，再探索。把手机收好再走路，海岸不边看屏幕边后退。'],['回住处形成闭环','每天挑5–10张，写一句为什么喜欢。检查云备份是否真正完成，必要时再保留独立副本；同步删除可能同时影响云端，不能简单当成独立备份。隐私照片不随意上传。']],steps:['出门前：镜头、电量、空间、格式、路线。','现场：全景—主体—细节；检查一张，再继续。','回住处：筛选—简单编辑—确认备份—写一条下次改进。','练习本里的照片只保存在当前浏览器，不是云备份；重要原片继续保留在系统照片与独立备份里。'],scene:'11月21–26日的旅行，每天用五张照片组成一页日记。遇到天气或交通变化，就调整题材，没必要完成所有拍摄清单。',tasks:['模拟一次校园半日旅行，最终只保留5张照片。','按“我想表达什么—我做了什么—下次改什么”写一段复盘。'],question:'浏览器练习本和云端同步是否等同于完整独立备份？',options:['是，保存过就永远不会丢','不是，需要检查保存位置和独立副本','不用保留原片'],answer:1,explain:'浏览器数据可能被清理；同步可能传播删除。重要照片需要明确且可靠的备份安排。',tip:'最好的工作流，是你旅行累了也愿意做的那一套。',refs:['photos']}
];
